window.MOTIF_CATALOG_CHUNKS[1]={"cards":[{"id":"ML-T01336","row_version":2,"title":"신정 체제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01330","tag_path":[],"summary":"종교 기관이나 신성한 권위가 통치의 정당성과 주요 결정을 직접 뒷받침하는 정치 체제를 묶는다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"신정 체제","entry_url":"cards/ML-T01336/index.html"},{"id":"ML-T01337","row_version":2,"title":"독재 체제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01330","tag_path":[],"summary":"권력이 한 통치자 또는 소수 집단에 집중되고 그 결정을 견제할 제도가 약한 정치 체제를 묶는다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"독재 체제","entry_url":"cards/ML-T01337/index.html"},{"id":"ML-T01338","row_version":3,"title":"기업 통치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01330","tag_path":[],"summary":"기업이 치안·법·복지·거주권처럼 보통 공적 기관이 맡는 기능을 실질적으로 운영하는 세계관의 통치 형태를 묶는다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"기업 통치","entry_url":"cards/ML-T01338/index.html"},{"id":"ML-T01461","row_version":2,"title":"우주선 기체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01454","tag_path":[],"summary":"우주선을 하나의 사물이나 기술 장치로 볼 때 선체·추진·거주 설비와 규모를 찾는 분류다.","accent":"#8E8263","tab":"#7D8FA3","facet":"사물·도구·자원","bookmark":"우주선 기체","entry_url":"cards/ML-T01461/index.html"},{"id":"ML-T01484","row_version":3,"title":"저주받은 물건","original":"Cursed Item","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01482","tag_path":[],"summary":"손에 넣거나 사용한 사람에게 해로운 초자연적 효과를 미치는 물건이다. 겉으로는 유용하거나 귀해 보여도 대가가 뒤따른다. 물건의 해로운 효과에도 벗어날 조건이 있다면 저주를 푸는 숨은 조건을 찾아야 한다.","accent":"#8E8263","tab":"#AF8665","facet":"사물·도구·자원","bookmark":"저주받은 물건","entry_url":"cards/ML-T01484/index.html"},{"id":"ML-T01495","row_version":4,"title":"비행 능력","original":"Flight","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":"tag","parent_id":"ML-T01490","tag_path":[],"summary":"인물이 날개나 초능력 등으로 지면을 떠나 원하는 방향으로 움직일 수 있는 능력이다. 비행을 마지막으로 익히는 성장 전개는 끝에 가서 완성되는 비행 능력에 해당한다. 날 수 있는 힘을 연인의 관계 변화에 쓰면 함께 날며 가까워지는 연인가 된다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"비행 능력","entry_url":"cards/ML-T01495/index.html"},{"id":"ML-T01509","row_version":3,"title":"순간이동","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":"tag","parent_id":"ML-T01508","tag_path":[],"summary":"이동 구간을 통상적인 속도로 지나가지 않고 한 장소에서 떨어진 다른 장소로 바로 옮겨 가는 능력·기술·규칙을 찾는 분류다.","accent":"#75799A","tab":"#8B739C","facet":"능력·기술·초자연","bookmark":"순간이동","entry_url":"cards/ML-T01509/index.html"},{"id":"ML-T01521","row_version":3,"title":"얼음 조작","original":"An Ice Person","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":"tag","parent_id":"ML-T01516","tag_path":[],"summary":"냉기와 얼음을 만들거나 움직여 전투, 이동, 환경 변화를 일으키는 능력. 얼음의 생성 범위와 유지 조건, 사용자가 추위에 받는 영향을 세계관 규칙으로 정한다.","accent":"#75799A","tab":"#A58A4E","facet":"능력·기술·초자연","bookmark":"얼음 조작","entry_url":"cards/ML-T01521/index.html"},{"id":"ML-T01533","row_version":4,"title":"생명 창조","original":"Creating Life","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":"tag","parent_id":"ML-T01525","tag_path":[],"summary":"마법이나 과학의 힘으로 새로운 살아 있는 존재를 만든다. 만들어진 존재의 자율성과 창조자의 책임이 뒤따른다. 창조자가 결과를 예상하지 못했다면 뜻밖에 태어난 생명의 사건으로 시작한다.","accent":"#75799A","tab":"#528982","facet":"능력·기술·초자연","bookmark":"생명 창조","entry_url":"cards/ML-T01533/index.html"},{"id":"ML-T01551","row_version":2,"title":"발동 조건","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":"group","parent_id":"ML-F17","tag_path":[],"summary":"능력이나 주문이 실제로 작동하기 전에 충족해야 하는 말·동작·재료·환경 조건을 찾는 태그다.","accent":"#75799A","tab":"#79866C","facet":"능력·기술·초자연","bookmark":"발동 조건","entry_url":"cards/ML-T01551/index.html"},{"id":"ML-T01552","row_version":2,"title":"주문 발화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":"tag","parent_id":"ML-T01551","tag_path":[],"summary":"정해진 말을 소리 내거나 특정 언어로 표현해야 주문이 시작되는 방식을 찾는 태그다.","accent":"#75799A","tab":"#79866C","facet":"능력·기술·초자연","bookmark":"주문 발화","entry_url":"cards/ML-T01552/index.html"},{"id":"ML-T01554","row_version":2,"title":"도구 매개","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":"tag","parent_id":"ML-T01551","tag_path":[],"summary":"능력을 쓰려면 특정 물건을 쥐거나 착용하거나 그 안에 효과를 담아 두어야 하는 설정을 찾는 태그다.","accent":"#75799A","tab":"#79866C","facet":"능력·기술·초자연","bookmark":"도구 매개","entry_url":"cards/ML-T01554/index.html"},{"id":"ML-T01555","row_version":2,"title":"혈통 조건","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":"tag","parent_id":"ML-T01551","tag_path":[],"summary":"가문이나 조상에게서 이어진 조건이 능력 사용 자격이나 강도에 영향을 주는 설정을 찾는 태그다.","accent":"#75799A","tab":"#79866C","facet":"능력·기술·초자연","bookmark":"혈통 조건","entry_url":"cards/ML-T01555/index.html"},{"id":"ML-T01718","row_version":5,"title":"꽃 이미지","original":"Flower Motifs","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":"tag","parent_id":"ML-T01711","tag_path":[],"summary":"작품에서 꽃이 인물이나 사건과 함께 반복되어 성격, 관계, 주제를 암시하는 상징적 이미지가 된다. 여성성을 알리는 꽃는 꽃을 여성성의 시각 기호로 쓰는 경우다. 자연과 이어진 인물의 꽃 장식는 꽃으로 인물의 자연 친화성을 나타내는 경우다. 연애의 뜻을 전하는 꽃는 꽃을 구애와 화해의 뜻을 전하는 데 사용하는 경우다.","accent":"#85835C","tab":"#778F70","facet":"상징·이미지","bookmark":"꽃 이미지","entry_url":"cards/ML-T01718/index.html"},{"id":"ML-T01741","row_version":2,"title":"왕관 이미지","original":"Cool Crown","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":"tag","parent_id":"ML-T01737","tag_path":[],"summary":"왕관을 인물의 지위, 통치권, 정통성 또는 위엄을 드러내는 시각적 표지로 쓰는 방식. 독특한 형태는 인물의 개성과 세계의 권력 구조를 함께 보여 준다.","accent":"#85835C","tab":"#528982","facet":"상징·이미지","bookmark":"왕관 이미지","entry_url":"cards/ML-T01741/index.html"},{"id":"ML-T01783","row_version":3,"title":"상징주의적 표현","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":"tag","parent_id":"ML-T01781","tag_path":[],"summary":"인물·사물·색·행동의 표면적 기능 너머에 추상적 의미를 강하게 싣는 시각·서사 표현을 찾는 분류다.","accent":"#947C8F","tab":"#778F70","facet":"미학·스타일","bookmark":"상징주의적 표현","entry_url":"cards/ML-T01783/index.html"},{"id":"ML-T01787","row_version":2,"title":"마술적 리얼리즘","original":"Magic Realism","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":"tag","parent_id":"ML-T01781","tag_path":[],"summary":"현실과 가까운 일상·사회 문제 속에 불가사의한 사건이 들어오되 인물들이 그것을 세계의 일부처럼 받아들이는 이야기의 표현 방식. 경이로운 요소가 있어도 그 자체를 해명하는 모험이 중심일 필요는 없다. 세계 안에서 실제로 작동하는 마법은 주문의 작동 여부를 다루는 다른 층위다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/ML-T01787/index.html"},{"id":"ML-T01795","row_version":4,"title":"아르누보풍","original":"Art Nouveau","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":"tag","parent_id":"ML-T01790","tag_path":[],"summary":"식물의 곡선과 유기적인 장식을 건물·포스터·가구·의상에 반복해 부드러운 흐름을 만든다. 작품의 분위기를 구성하는 시각 양식으로 다룬다. 직선과 대칭을 앞세우는 아르데코풍과 곡선 중심의 인상을 비교할 수 있다.","accent":"#947C8F","tab":"#8B739C","facet":"미학·스타일","bookmark":"아르누보풍","entry_url":"cards/ML-T01795/index.html"},{"id":"ML-T01796","row_version":2,"title":"아르데코풍","original":"Art Deco","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":"tag","parent_id":"ML-T01790","tag_path":[],"summary":"기하학적 무늬와 대칭, 유선형 장식을 건물·가구·의상에 반복해 특정 시대의 도시적 인상을 만든다. 양식의 역사 자체보다 작품에서 쓰인 시각 언어를 다룬다.","accent":"#947C8F","tab":"#8B739C","facet":"미학·스타일","bookmark":"아르데코풍","entry_url":"cards/ML-T01796/index.html"},{"id":"ML-T01886","row_version":3,"title":"더치 앵글","original":"Dutch Angle","aliases":["Dutch Angle","더치 틸트","기울어진 화면"],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01882","tag_path":[],"summary":"카메라를 수평에서 비스듬히 기울여 불안정하거나 낯선 느낌을 만드는 촬영 구도.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"더치 앵글","entry_url":"cards/ML-T01886/index.html"},{"id":"ML-T01892","row_version":3,"title":"팬","original":"Pan","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01891","tag_path":[],"summary":"카메라를 한 위치에 둔 채 좌우로 회전시켜 화면이 바라보는 방향을 바꾸는 촬영 기법이다. 인물을 따라가거나 공간을 차례로 드러낼 때 사용한다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"팬","entry_url":"names/724cc77d2d75c51c/index.html"},{"id":"ML-T01990","row_version":3,"title":"말장난","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"소리·철자·뜻의 겹침이나 엇갈림을 이용해 두 가지 이상의 해석을 만드는 언어 표현을 찾는 분류다.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"말장난","entry_url":"cards/ML-T01990/index.html"},{"id":"ML-T02083","row_version":2,"title":"안개 지도","original":"Fog of War","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02079","tag_path":[],"summary":"전략 게임에서 아직 탐색하지 않았거나 현재 관측할 수 없는 구역과 적 정보를 화면에서 숨기는 규칙이다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"안개 지도","entry_url":"cards/ML-T02083/index.html"},{"id":"ML-T02121","row_version":2,"title":"요리 시스템","original":"Cooking Mechanics","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"플레이어가 재료를 조합해 음식을 만들고 그 결과를 회복이나 진행에 사용하는 게임 규칙.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"요리 시스템","entry_url":"cards/ML-T02121/index.html"},{"id":"ML-T02139","row_version":3,"title":"체크포인트","original":"Checkpoint","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02133","tag_path":[],"summary":"게임 진행 중 실패하거나 중단해도 다시 시작할 수 있도록 정해 둔 지점. 돌아갈 위치의 간격이 위험을 감수하는 방식에 영향을 준다. 체크포인트가 드문 구간에서는 다시 시작할 지점이 멀어져 실패의 부담이 커진다.","accent":"#667E94","tab":"#79866C","facet":"게임·상호작용","bookmark":"체크포인트","entry_url":"cards/ML-T02139/index.html"},{"id":"ML-T02262","row_version":2,"title":"원작 각색","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":"tag","parent_id":"ML-T02261","tag_path":[],"summary":"원작의 인물·사건·세계 규칙을 다른 매체나 형식에 맞게 다시 구성하는 제작 과정. 유지할 핵심과 바꿀 요소를 정하는 선택이 새로운 해석을 만든다.","accent":"#7F8A85","tab":"#8B739C","facet":"메타·제작·유통","bookmark":"원작 각색","entry_url":"cards/ML-T02262/index.html"},{"id":"ML-T02279","row_version":3,"title":"배우 교체","original":"Actor Swap","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":"tag","parent_id":"ML-T02277","tag_path":[],"summary":"작품 속 같은 배역을 다른 배우가 이어 맡거나 한 작품 안에서 나누어 맡는 제작 방식. 인물은 이어져도 외형과 연기의 결이 달라져 관객이 연속성을 받아들이는 방법을 새로 정해야 한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/ML-T02279/index.html"},{"id":"MM-UNSET-000002","row_version":2,"title":"조연 중심 회차","original":"A Day in the Limelight","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"연속·에피소드 작품에서 평소 조연이나 배경 역할인 인물에게 한 회차의 주요 시점과 사건을 집중해 관계·성격·이야기 가능성을 확장하는 구성. 앙상블 작품에서는 특정 인물의 경험을 잠시 중심에 놓는 방식으로도 쓰인다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MM-UNSET-000002/index.html"},{"id":"MM-UNSET-000003","row_version":2,"title":"종류를 그대로 이름 삼기","original":"A Dog Named \"Dog\"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01993"],"summary":"반려동물·로봇 등에게 종이나 역할을 그대로 부르는 이름을 붙여 단순한 작명이나 무심한 태도를 드러내는 표현. 다른 언어의 종명을 이름으로 쓰는 변형도 포함한다.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"언어 장치","entry_url":"cards/MM-UNSET-000003/index.html"},{"id":"MM-UNSET-000007","row_version":2,"title":"불가능한 물체까지 베는 힘","original":"Absurd Cutting Power","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"보통의 칼날로는 손상시키기 어려운 물체나 방어까지 단번에 가르는 능력. 인물의 숙련, 특수 기술, 무기·방어구의 성능처럼 힘의 근거를 다르게 설정할 수 있다. 무엇을 벨 수 없느냐가 이 능력의 한계와 갈등을 만든다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MM-UNSET-000007/index.html"},{"id":"MEJE-KW-000230","row_version":1,"title":"뜻밖의 대상을 두려워하는 인물","original":"Absurd Phobia","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"작품 속 인물이 주변 사람에게는 무해하거나 사소해 보이는 대상을 유난히 두려워하는 설정. 두려움의 대상과 인물의 반응 사이의 예상 밖 간격이 장면의 긴장이나 웃음을 만든다. 실제 공포증에 대한 일반화나 조롱으로 확대하지 않는다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-000230/index.html"},{"id":"MEJE-KW-000231","row_version":1,"title":"순진한 상징을 뒤집은 유니콘","original":"Absurdicorn","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"유니콘에 기대하는 순수하고 온화한 이미지를 깨고 기괴하거나 거친 행동을 하는 존재로 그리는 변형. 익숙한 외형은 남겨 두되 말투와 행동을 뒤집어 세계의 낯선 분위기나 블랙코미디를 드러낸다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000231/index.html"},{"id":"MEJE-KW-000232","row_version":1,"title":"부조리주의","original":"Absurdism","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"삶에서 의미와 질서를 찾으려는 인간의 기대가 세계의 침묵이나 비논리적인 사건과 부딪힌다는 관점. 작품에서는 반복되지만 목적에 닿지 않는 행동, 어긋나는 대화, 설명되지 않는 상황으로 표현될 수 있다. 부조리 코미디는 이 간극을 웃음으로 다루는 한 방식이다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-000232/index.html"},{"id":"MEJE-KW-000233","row_version":2,"title":"터무니없이 밝은 조명","original":"Absurdly Bright Light","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22","ML-T01863"],"summary":"작은 조명이나 손전등에서 상식적인 규모를 훌쩍 넘는 빛이 뻗어 나가는 시각적 과장. 빛이 닿는 거리나 주변 인물의 반응을 크게 잡아 장치의 위력 또는 코미디 효과를 즉시 보여 준다. 일반적인 빛 이미지와 달리 밝기의 불가능한 크기가 중심이다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"조명·색채","entry_url":"cards/MEJE-KW-000233/index.html"},{"id":"MEJE-KW-000234","row_version":1,"title":"압도적인 경관의 미래도시","original":"Absurdly Cool City","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01303","ML-T01304"],"summary":"한눈에 세계의 기술력이나 사회 질서를 드러내도록 설계한 인상적인 가상 도시. 대도시의 규모, 층위, 교통과 빛의 배치를 크게 강조할 수 있으며 같은 장관이라도 낙관적인 이상향이나 위압적인 통제 사회를 나타낼 수 있다.","accent":"#68838D","tab":"#79866C","facet":"시공간·환경","bookmark":"대도시","entry_url":"cards/MEJE-KW-000234/index.html"},{"id":"MEJE-KW-000235","row_version":1,"title":"목적이 사라져도 임무를 계속하는 일꾼","original":"Absurdly Dedicated Worker","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00916"],"summary":"맡은 일이 더는 필요하지 않거나 지시자가 사라졌는데도 정해진 임무를 계속 수행하는 인물 또는 기계. 주변 세계의 변화와 한결같은 행동 사이의 간격이 비극, 불안, 웃음을 만들며 노동자와 자동화 장치 모두에 적용할 수 있다.","accent":"#7B7594","tab":"#528982","facet":"인물","bookmark":"직업·기능","entry_url":"cards/MEJE-KW-000235/index.html"},{"id":"MEJE-KW-000236","row_version":1,"title":"파벌로 갈라진 학교","original":"Absurdly Divided School","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01364","ML-T01365"],"summary":"학교의 무리나 반 배정이 학생 사이의 일상적 구분을 넘어 협력과 이동까지 막는 강한 파벌 질서가 된 설정. 소속 집단끼리 서로를 경계하거나 경쟁하며, 경계를 넘는 인물의 선택이 갈등의 출발점이 된다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"학교 조직","entry_url":"cards/MEJE-KW-000236/index.html"},{"id":"MEJE-KW-000237","row_version":1,"title":"늦은 나이에 자녀를 맞은 아버지","original":"Absurdly Elderly Father","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970","ML-T00971"],"summary":"자녀가 성장하는 시기와 아버지의 노년이 겹치도록 배치한 부모와 자녀 관계 설정. 두 세대의 시간 감각과 양육의 기대가 어긋나는 장면을 만들 수 있다. 나이만으로 건강이나 양육 능력을 단정하지 않는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"부모와 자녀","entry_url":"cards/MEJE-KW-000237/index.html"},{"id":"MEJE-KW-000238","row_version":1,"title":"고령에 새 자녀를 둔 어머니","original":"Absurdly Elderly Mother","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970","ML-T00971"],"summary":"높은 연령에 어린 자녀를 둔 어머니를 통해 부모와 자녀의 시간 차이를 드러내는 설정. 주변이 조부모와 손주로 오인하거나 생애 계획이 바뀌는 장면으로 쓰인다. 실제 출산 가능성이나 건강을 특정 나이만으로 단정하지 않는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"부모와 자녀","entry_url":"cards/MEJE-KW-000238/index.html"},{"id":"MEJE-KW-000239","row_version":1,"title":"지나치게 까다로운 모집 기준","original":"Absurdly Exclusive Recruiting Standards","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01364"],"summary":"소수만 받아들이려는 조직이 실력·신원·적합성을 지나치게 촘촘하게 가려 신규 구성원이 거의 생기지 않는 설정. 임무의 위험, 희소한 재능, 권위 과시 중 무엇을 이유로 삼는지에 따라 조직의 성격이 드러난다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"조직·기관","entry_url":"cards/MEJE-KW-000239/index.html"},{"id":"MEJE-KW-000240","row_version":1,"title":"실제 필요보다 훨씬 높은 수치 상한","original":"Absurdly High Cap","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02088"],"summary":"게임의 능력치나 자원 수치가 보통의 진행에 필요한 범위를 훨씬 넘어서까지 누적되도록 허용된 규칙. 도달하기 어려운 수치도 최고치로 표시해 장기 플레이나 극단적인 성장 목표를 남겨 둔다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"진행·성장","entry_url":"cards/MEJE-KW-000240/index.html"},{"id":"MEJE-KW-000241","row_version":1,"title":"진행에 필요 없는 초고레벨 상한","original":"Absurdly High Level Cap","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02088"],"summary":"레벨업의 최대치가 본편을 마칠 때 도달하는 수준보다 훨씬 높게 설정된 게임 규칙. 엔딩을 보기 위한 성장과 상한까지 도달하려는 장기 반복 플레이가 서로 다른 목표가 된다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"진행·성장","entry_url":"cards/MEJE-KW-000241/index.html"},{"id":"MEJE-KW-000242","row_version":2,"title":"삶까지 걸게 하는 승부","original":"Absurdly High-Stakes Game","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"평범한 승부에 생계·가족·신체 또는 목숨처럼 큰 대가를 걸어 인물이 결과를 두려워하게 하는 서사 장치. 판돈의 크기보다 패배 뒤 실제로 무엇을 잃는지가 장면의 갈등을 만든다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-000242/index.html"},{"id":"MEJE-KW-000243","row_version":1,"title":"상상을 초월하는 인구 규모","original":"Absurdly Huge Population","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"도시·국가·행성의 인구를 상상을 넘는 규모로 설정해 문명의 크기와 시간의 경과를 전달한다. 숫자 자체뿐 아니라 주거·식량·이동 체계가 그 규모를 어떻게 감당하는지가 세계 설정의 설득력을 좌우한다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000243/index.html"},{"id":"MEJE-KW-000244","row_version":1,"title":"허술한 바리케이드","original":"Absurdly Ineffective Barricade","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08","ML-T00858"],"summary":"위협을 막으려고 통로를 막지만 재료가 약하거나 다른 길이 열려 있어 거의 시간을 벌지 못하는 장면. 무엇을 막아야 하는지와 공간을 어떻게 읽었는지의 차이가 긴장이나 웃음을 만든다.","accent":"#936E72","tab":"#7D8FA3","facet":"갈등·장애","bookmark":"조건 장애","entry_url":"cards/MEJE-KW-000244/index.html"},{"id":"MEJE-KW-000245","row_version":1,"title":"끝없이 긴 리무진","original":"Absurdly Long Limousine","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01454"],"summary":"지나치게 늘어난 리무진의 길이 자체가 부와 과시를 웃음으로 보여 주는 소품. 등장·회전·정차에 걸리는 시간을 늘려 한 장면을 시각적 농담으로 만든다.","accent":"#8E8263","tab":"#7D8FA3","facet":"사물·도구·자원","bookmark":"이동 수단","entry_url":"cards/MEJE-KW-000245/index.html"},{"id":"MEJE-KW-000246","row_version":1,"title":"끝없이 이어지는 계단","original":"Absurdly Long Stairway","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313"],"summary":"도착점이 보이지 않을 만큼 길거나 끝없이 이어지는 계단. 올라가는 행위 자체를 시련으로 바꾸고, 공간의 압도적 규모나 인물의 피로를 드러낸다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"특수 공간","entry_url":"cards/MEJE-KW-000246/index.html"},{"id":"MEJE-KW-000247","row_version":1,"title":"지나치게 긴 대기 시간","original":"Absurdly Long Wait","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"평소라면 짧게 끝날 절차가 며칠이나 몇 년까지 늘어나는 시간 과장. 기다리는 대상이 사소할수록 대기의 규모와 목적 사이의 불균형이 웃음이나 제도의 답답함을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-000247/index.html"},{"id":"MEJE-KW-000248","row_version":1,"title":"쉽게 닿는 낮은 레벨 상한","original":"Absurdly Low Level Cap","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02088"],"summary":"최대 레벨에 도달하기 쉬워 본편을 끝내기 전에 성장 수치가 멈추는 게임 규칙. 상한 숫자의 절대값보다 플레이 도중 얼마나 빨리 한계에 닿는지가 중요하며 레벨업의 보상 흐름을 바꾼다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"진행·성장","entry_url":"cards/MEJE-KW-000248/index.html"},{"id":"MEJE-KW-000249","row_version":1,"title":"학교 밖까지 미치는 징계권","original":"Absurdly Powerful School Jurisdiction","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01364","ML-T01365"],"summary":"학교 밖이나 수업 밖에서 벌어진 일에도 학교가 징계권을 주장하는 설정. 학교 조직의 통제 범위가 학생의 생활 전체로 확장될 때 사생활과 자율성이 갈등의 대상이 된다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"학교 조직","entry_url":"cards/MEJE-KW-000249/index.html"},{"id":"MEJE-KW-000250","row_version":1,"title":"막강한 학생회","original":"Absurdly Powerful Student Council","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01364","ML-T01365"],"summary":"학생 대표 기구가 교직원이나 학교 운영진을 능가하는 권한을 가진 설정. 학교 조직의 의사결정 중심이 학생에게 옮겨지면서 선거·파벌·규칙 제정이 권력 다툼의 재료가 된다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"학교 조직","entry_url":"cards/MEJE-KW-000250/index.html"},{"id":"MEJE-KW-000251","row_version":1,"title":"이상할 만큼 날카로운 칼날","original":"Absurdly Sharp Blade","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01408"],"summary":"특별한 주문이나 작동 장치보다 칼날 자체의 날카로움으로 통상 베기 어려운 대상을 절단하는 무기·방어구 설정. 불가능한 물체까지 베는 힘의 근거가 인물의 초능력이 아니라 물건의 물성에 있다는 점이 핵심이다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"무기·방어구","entry_url":"cards/MEJE-KW-000251/index.html"},{"id":"MEJE-KW-000252","row_version":1,"title":"비정상적으로 날카로운 발톱","original":"Absurdly Sharp Claws","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"동물이나 괴물의 발톱을 자연적으로 자란 칼날처럼 그리는 설정. 별도 무기 없이 단단한 물질을 가를 만큼 날카로운 신체 부위가 그 존재의 위협을 보여 준다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000252/index.html"},{"id":"MEJE-KW-000253","row_version":1,"title":"순식간에 끝나는 게임 레벨","original":"Absurdly Short Level","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02088"],"summary":"다른 스테이지보다 훨씬 짧게 끝나는 게임 구간. 간단한 조작을 가르치거나 허를 찌르는 농담으로 쓰이며, 짧아 보이는 필수 경로 뒤에 선택 탐색을 숨길 수도 있다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"진행·성장","entry_url":"cards/MEJE-KW-000253/index.html"},{"id":"MEJE-KW-000254","row_version":1,"title":"유난히 짧은 실제 제작 기간","original":"Absurdly Short Production Time","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277"],"summary":"한 작품의 촬영·제작·조립 같은 실제 제작 단계가 통상 예상보다 짧게 끝난 경우를 가리킨다. 기획과 배급을 기다린 시간은 실질 제작 기간과 구별해 기록한다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"제작 관행","entry_url":"cards/MEJE-KW-000254/index.html"},{"id":"MEJE-KW-000255","row_version":1,"title":"사람이 다니는 거대한 하수도","original":"Absurdly Spacious Sewer","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313"],"summary":"배수 시설을 넘어 사람이 서서 이동하거나 집단이 거주할 만큼 넓은 하수도 공간. 추격·은신·지하 생활의 무대로 쓰이며, 작품 안에서는 통로의 유지와 환경 조건을 설명할수록 설득력이 높아진다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"특수 공간","entry_url":"cards/MEJE-KW-000255/index.html"},{"id":"MEJE-KW-000256","row_version":1,"title":"자녀와 또래처럼 보이는 어머니","original":"Absurdly Youthful Mother","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970","ML-T00971"],"summary":"어머니가 자녀와 나이 차가 거의 없어 보이거나 실제로 가까운 설정. 주변의 오인과 관계의 거리감을 만들 수 있으나 외모의 젊음과 실제 출산 연령은 별개의 이야기다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"부모와 자녀","entry_url":"cards/MEJE-KW-000256/index.html"},{"id":"MEJE-KW-000257","row_version":1,"title":"학대 장면을 화면 밖으로 돌리는 연출","original":"Abuse Discretion Shot","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22","ML-T01908"],"summary":"학대가 벌어지는 장면을 정면으로 보여 주지 않고 반응·소리·그림자·사후 흔적으로 전달하는 연출. 피해 사실을 이해시키면서 직접 묘사의 수위와 관객이 아는 정보의 양을 조절한다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"편집·연결","entry_url":"cards/MEJE-KW-000257/index.html"},{"id":"MEJE-KW-000258","row_version":1,"title":"가해 행위가 단계적으로 심해지기","original":"Abuse Escalation","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08","ML-T00831"],"summary":"한 인물이 다른 사람에게 가하는 학대가 이야기의 흐름에 따라 빈도나 강도에서 더 심해지는 전개. 앞선 행동과 뒤의 행동이 비교되면서 관계의 위험이 드러난다.","accent":"#936E72","tab":"#778F70","facet":"갈등·장애","bookmark":"관계 갈등","entry_url":"cards/MEJE-KW-000258/index.html"},{"id":"MEJE-KW-000259","row_version":2,"title":"학대 의심이 빚은 오해","original":"Abuse Mistake","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물들이 무해한 상황을 학대로 오해해 섣불리 개입하는 서사. 오해가 생긴 단서와 사실 확인 과정이 사건의 핵심이며, 현실의 피해 신고를 가볍게 다루는 일반론으로 확대하지 않는다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000259/index.html"},{"id":"MEJE-KW-000260","row_version":2,"title":"반품을 공짜 대여처럼 쓰기","original":"Abuse of Return Policy","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00757"],"summary":"물건을 잠시 쓰고 반품해 구매 비용을 돌려받으려는 인물의 행동. 사용 흔적이나 영수증 문제로 계획이 어긋나면 생활 코미디의 사건이 된다.","accent":"#9B7160","tab":"#A58A4E","facet":"사건·행동","bookmark":"거래·약속","entry_url":"cards/MEJE-KW-000260/index.html"},{"id":"MEJE-KW-000001","row_version":2,"title":"위험 탈것에서의 긴급 대피","original":"Abandon Ship","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00747"],"summary":"선박·항공기·우주선 등 탑승한 탈것이 침몰·추락·폭발 위험에 놓이자 인물들이 탈출 수단을 찾아 대피하는 위기 장면. 퇴선 명령, 제한된 시간, 누군가를 남겨 두거나 책임자가 탈것과 함께 남는 선택을 통해 긴장과 희생을 드러낼 수 있다.\n\n탑승자를 내보내는 수단으로 탈출 포드가 쓰일 수 있으며, 남은 인원을 두고 떠날지의 선택이 긴장을 키운다.","accent":"#9B7160","tab":"#8B739C","facet":"사건·행동","bookmark":"이동·경계","entry_url":"cards/MEJE-KW-000001/index.html"},{"id":"MEJE-KW-000002","row_version":2,"title":"희귀 혈액형 서사 장치","original":"AB Negative","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"작품에서 흔치 않은 혈액형을 긴급 수혈, 인물 식별, 납치나 거래의 조건으로 사용해 사건의 긴장이나 인물의 취약성을 만드는 서사 장치. 현실의 혈액형·수혈 의학에 관한 안내가 아니라 허구에서의 활용 패턴을 가리킨다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-000002/index.html"},{"id":"MEJE-KW-000003","row_version":1,"title":"짐승이라 불리는 인물","original":"A Beast in Name and Nature","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물에게 ‘짐승’이라는 이름이나 별칭을 붙여 외형·행동·위협성을 한데 묶어 보이는 명명 관습. 이름이 단순한 호칭을 넘어 인물의 성격이나 작품 속 상징을 강화한다. 실제 동물형 존재와 사람을 비유한 표현은 맥락에 따라 구별한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000003/index.html"},{"id":"MEJE-KW-000004","row_version":2,"title":"서사 전환점이 되는 생일","original":"A Birthday, Not a Break","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06","ML-T00679"],"summary":"생일이라는 축하 시점에 이별·상실·폭로나 공격 같은 사건을 겹쳐 기념일과 위기의 대비를 키우거나, 생일 모임을 인물들이 한자리에 모이고 갈등이 드러나는 계기로 쓰는 서사 장치.","accent":"#88734E","tab":"#778F70","facet":"서사 기능","bookmark":"발동·추진","entry_url":"cards/MEJE-KW-000004/index.html"},{"id":"MEJE-KW-000005","row_version":1,"title":"붉은 얼룩을 피로 오인","original":"A Bloody Mess","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22","ML-T01863"],"summary":"케첩이나 물감처럼 붉은 얼룩을 실제 피로 착각해 놀라거나 소동을 벌이는 장면. 오해 자체가 시각적 웃음으로 쓰이거나, 누군가 부상을 꾸미는 수단이 되기도 한다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"조명·색채","entry_url":"cards/MEJE-KW-000005/index.html"},{"id":"MEJE-KW-000006","row_version":1,"title":"남매와 아기 막내 구성","original":"A Boy, a Girl, and a Baby Family","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970"],"summary":"두 명의 나이 든 남매와 아직 어린 막내 아기를 둔 가족 구성을 인물 기본형으로 쓰는 방식. 서로 다른 연령대의 자녀를 한 가족 안에 배치해 형제 관계와 역할 차이를 만드는 서사적 인물 배열이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"가족·친족","entry_url":"cards/MEJE-KW-000006/index.html"},{"id":"MEJE-KW-000007","row_version":2,"title":"주인공과 특별한 동반자의 성장","original":"A Boy and His X","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00996"],"summary":"어린 주인공의 삶에 특별한 존재가 들어오고 관계를 맺으며 함께 변해 가는 이야기 구성. 동반자는 동물·괴물 등 비인간일 수 있으며, 관계의 변화가 주인공의 성장이나 성인기로의 이행을 이끈다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"우정·동료","entry_url":"cards/MEJE-KW-000007/index.html"},{"id":"MEJE-KW-000008","row_version":1,"title":"잘못된 음절 강세","original":"AcCENT upon the Wrong SylLABle","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01993"],"summary":"낱말의 강세를 엉뚱한 음절에 두어 어색함·오해·인물의 언어 감각을 드러내거나 웃음을 만드는 언어 연출. 노래의 운율이나 제2언어 화자의 말투처럼 의도와 실수가 함께 작동할 수 있다.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"언어 장치","entry_url":"cards/MEJE-KW-000008/index.html"},{"id":"MEJE-KW-000009","row_version":1,"title":"등장인물의 만능 공급처","original":"ACME Products","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01364"],"summary":"여러 인물에게 도구·무기·서비스 등 필요한 것을 두루 공급하는 범용 기업이나 상점을 설정하는 방식. 상품의 결함이나 반복되는 공급은 개그가 되거나 사건을 빠르게 전개하는 장치로 쓰일 수 있다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"조직·기관","entry_url":"cards/MEJE-KW-000009/index.html"},{"id":"MEJE-KW-000010","row_version":1,"title":"무반주 노래","original":"A cappella","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24","ML-T02045"],"summary":"악기 반주 없이 목소리만으로 선율·화음·리듬을 만드는 노래나 합창 방식. 집단의 호흡, 보컬 기량, 즉흥적인 음악 표현을 보여주는 매체·연출 요소로 활용된다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"목소리·가창","entry_url":"cards/MEJE-KW-000010/index.html"},{"id":"MEJE-KW-000011","row_version":2,"title":"개 무리 속 유일한 고양이","original":"A Cat in a Gang of Dogs","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00907","ML-T00913"],"summary":"개 캐릭터가 다수를 이루는 무리나 팀에 고양이 한 마리를 배치해 종과 성향의 대비를 만드는 인물 구성. 고양이는 집단의 익숙한 규범과 다른 시각을 보태거나 구성원 사이의 균형을 맡을 수 있다.","accent":"#7B7594","tab":"#A58A4E","facet":"인물","bookmark":"아웃사이더","entry_url":"cards/MEJE-KW-000011/index.html"},{"id":"MEJE-KW-000012","row_version":2,"title":"내면의 그림자를 마주하는 관문","original":"A Chat with Satan","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06","ML-T00693"],"summary":"주인공이 운명이나 성취에 이르기 전, 악마·그림자 같은 존재와 대면하며 자신의 약점이나 욕망을 드러내고 시험받는 서사 단계. 그 대면에서 내린 선택이 이후의 자격이나 행로를 가른다.","accent":"#88734E","tab":"#A58A4E","facet":"서사 기능","bookmark":"인물 변화","entry_url":"cards/MEJE-KW-000012/index.html"},{"id":"MEJE-KW-000013","row_version":1,"title":"미성년 통치자와 섭정","original":"A Child Shall Lead Them","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00907"],"summary":"미성년자가 왕위나 국가 지도권을 맡고, 경험 부족과 공식 권한 사이의 긴장 속에서 섭정·보좌관·권력 경쟁자와 관계를 맺는 인물 구도. 어린 통치자의 선택과 주변 세력의 개입이 권력 갈등을 움직인다.","accent":"#7B7594","tab":"#A58A4E","facet":"인물","bookmark":"사회적 위치","entry_url":"cards/MEJE-KW-000013/index.html"},{"id":"MEJE-KW-000014","row_version":1,"title":"차별화된 게임 진영 설계","original":"A Commander Is You","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02106"],"summary":"전략 게임에서 플레이어가 고르는 진영마다 생산 규모·전투 방식·기동성 등 강점과 제약을 달리해 서로 다른 운영 전략을 만드는 설계. 진영 간 차이는 선택의 의미와 게임 내 상성을 형성한다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"전투·경쟁","entry_url":"cards/MEJE-KW-000014/index.html"},{"id":"MEJE-KW-000015","row_version":1,"title":"눈에 가려진 빙하 틈의 위기","original":"A Crack in the Ice","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01274","ML-T01284"],"summary":"눈이나 약한 표면에 가려진 빙하 균열을 뒤늦게 발견해 인물이 떨어지거나, 이를 건너는 눈다리가 무너질 위험에 놓이는 환경 위기. 극지 공간의 이동을 위태롭게 만들고 구조와 동료의 대응을 이끈다.","accent":"#68838D","tab":"#528982","facet":"시공간·환경","bookmark":"극지","entry_url":"cards/MEJE-KW-000015/index.html"},{"id":"MEJE-KW-000016","row_version":2,"title":"외모 기준에서 비롯된 신체 불안","original":"A-Cup Angst","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"작은 체형이나 특정 신체 특성이 이상적 외모 기준과 다르다고 여겨 인물이 매력·성숙도·관계에서 불안을 느끼는 서사 구도. 인물의 신체를 결함으로 판정하기보다 주변의 평가와 미 기준이 만드는 압박을 드러낸다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-000016/index.html"},{"id":"MEJE-KW-000019","row_version":1,"title":"모험가형 고고학자","original":"Adventurer Archaeologist","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00916"],"summary":"작품에서 고고학자를 유적 탐험가로 그려 고대 유적·함정·유물·초자연적 위험을 직접 돌파하게 하는 인물 원형. 조사 과정은 압축되고 발견과 모험이 전면에 놓인다. 현실의 고고학 활동과는 구별해 읽는다.","accent":"#7B7594","tab":"#528982","facet":"인물","bookmark":"직업·기능","entry_url":"cards/MEJE-KW-000019/index.html"},{"id":"MEJE-KW-000020","row_version":1,"title":"가면 뒤의 과감한 자아","original":"A Darker Me","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"가상 인격이나 별도 페르소나가 현실의 인물보다 더 대담하고 공격적인 면을 대신 표출하는 구도. 평소 억제된 말투나 욕망이 드러나며, 그 해방감이 무례나 가해로 기울 수 있는 긴장을 만든다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-000020/index.html"},{"id":"MEJE-KW-000261","row_version":2,"title":"구매를 위협하는 과장 광고","original":"Abusive Advertising","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02254","ML-T02260"],"summary":"상품을 사지 않으면 손해를 보거나 벌을 받는다는 식으로 소비자를 위협하는 허구의 광고 연출. 불필요하게 공격적인 판매 문구 자체가 풍자나 코미디의 소재가 된다.","accent":"#7F8A85","tab":"#778F70","facet":"메타·제작·유통","bookmark":"극중 광고","entry_url":"cards/MEJE-KW-000261/index.html"},{"id":"MEJE-KW-000262","row_version":1,"title":"외계 부모의 가혹한 양육","original":"Abusive Alien Parents","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970","ML-T00971"],"summary":"인간과 다른 생물학이나 관습을 가진 부모가 자녀에게 위험한 시험이나 가혹한 대우를 강요하는 설정. 낯선 종족의 기준과 자녀가 겪는 피해 사이의 간극이 갈등을 만든다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"부모와 자녀","entry_url":"cards/MEJE-KW-000262/index.html"},{"id":"MEJE-KW-000263","row_version":1,"title":"학대 관계를 비추는 괴물 은유","original":"Abusive Monster Metaphor","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"인물 곁을 떠나지 않는 괴물이나 위협적인 존재를, 벗어나기 어려운 학대 관계의 은유로 쓰는 연출. 괴물의 행동은 관계에서 느끼는 공포와 통제감을 시각화한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-000263/index.html"},{"id":"MEJE-KW-000264","row_version":2,"title":"부모를 해치는 자녀","original":"Abusive Offspring","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970","ML-T00971"],"summary":"자녀가 부모를 반복적으로 위협하거나 착취하며 가족 내 권력 관계를 뒤집는 서사적 상황. 부모와 자녀 관계의 갈등을 자녀의 가해 행동에서 시작해 전개한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"부모와 자녀","entry_url":"cards/MEJE-KW-000264/index.html"},{"id":"MEJE-KW-000265","row_version":1,"title":"자녀를 해치는 부모","original":"Abusive Parents","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970","ML-T00971"],"summary":"부모가 자녀에게 반복적으로 폭력이나 방임, 통제를 가해 부모와 자녀 관계를 위협하는 설정. 자녀의 선택과 성장, 가족 이탈의 동기가 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"부모와 자녀","entry_url":"cards/MEJE-KW-000265/index.html"},{"id":"MEJE-KW-000266","row_version":1,"title":"다정했던 인물의 가해적 변화","original":"Abusive Personality Shift","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"처음에는 다정하게 보이던 인물이 관계가 깊어진 뒤 통제하거나 위협하는 모습을 드러내는 전개. 초반의 인상과 이후 행동의 차이가 피해 인물과 독자의 판단을 흔든다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000266/index.html"},{"id":"MEJE-KW-000267","row_version":1,"title":"후대를 해치려는 선대 문명","original":"Abusive Precursors","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"선대 문명이 후대의 종족이나 문명이 발견할 것을 알면서도 위험한 유산을 의도적으로 남기는 설정. 남겨진 기술이나 장치가 단순한 방치가 아니라 후대에 대한 적의를 드러낸다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000267/index.html"},{"id":"MEJE-KW-000268","row_version":1,"title":"착취가 조직 문화가 된 일터","original":"Abusive Workplace","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"노동자에게 과도한 요구와 모욕이 반복되며 그것이 예외가 아니라 일터의 관행처럼 굳어진 설정. 개인 상사 한 명보다 조직 전체의 규칙과 분위기가 갈등의 원인이 된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000268/index.html"},{"id":"MEJE-KW-000269","row_version":1,"title":"학력을 내세운 우월감","original":"Academia Elitism","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"학교의 명성이나 학위 수준을 근거로 다른 인물의 능력과 가치를 낮춰 보는 태도. 실제 성과보다 학력 서열을 앞세우면서 일터나 공동체에서 갈등을 만든다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000269/index.html"},{"id":"MEJE-KW-000270","row_version":1,"title":"성적과 인기 모두 쥐려는 우등생","original":"Academic Alpha Bitch","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"학업 성취를 무기로 또래 집단의 주도권까지 차지하려는 학생 인물형. 성적 경쟁을 인간관계의 서열로 넓히고, 다른 학생에게 역할을 지시하며 반발을 부른다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000270/index.html"},{"id":"MEJE-KW-000271","row_version":1,"title":"공부와 운동을 겸비한 선수","original":"Academic Athlete","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"운동 실력과 학업 성취를 함께 갖춘 학생 선수 인물형. 두 분야의 진로가 동시에 열리거나 충돌하면서 선택의 장면을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000271/index.html"},{"id":"MEJE-KW-000272","row_version":2,"title":"사건이 끊이지 않는 학교","original":"Academy of Adventure","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01285","ML-T01287"],"summary":"학교 자체가 납치, 비밀 통로, 낯선 존재의 출현 같은 모험 사건을 계속 끌어들이는 배경. 평범한 수업과 예측할 수 없는 사건의 간격이 학생 인물의 탐험을 이끈다.","accent":"#68838D","tab":"#7D8FA3","facet":"시공간·환경","bookmark":"학교","entry_url":"cards/MEJE-KW-000272/index.html"},{"id":"MEJE-KW-000273","row_version":1,"title":"악당 양성 학교","original":"Academy of Evil","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01364","ML-T01365"],"summary":"악당이 될 학생을 모집해 범죄나 권력 행사에 필요한 기술을 가르치는 허구의 교육 기관. 통상적인 학교의 수업과 규율을 악역의 목표에 맞춰 뒤집어 보인다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"학교 조직","entry_url":"cards/MEJE-KW-000273/index.html"},{"id":"MEJE-KW-000274","row_version":1,"title":"번역에서 억양 바꿔 옮기기","original":"Accent Adaptation","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"원작 인물이 쓰는 지역 말투의 차이를 번역 언어에서 다른 지역 말투로 바꾸어 표현하는 각색. 단어의 뜻뿐 아니라 말투가 전달하던 인물 관계와 분위기를 옮기려는 선택이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000274/index.html"},{"id":"MEJE-KW-000275","row_version":1,"title":"억양에 좌우되는 말장난","original":"Accent Depundent","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01982","ML-T01990"],"summary":"같은 언어를 쓰더라도 지역이나 집단의 발음 차이에 따라 이해되거나 사라지는 말장난. 특정 발음에서만 운율과 동음이 맞아 언어권 내부에서도 반응이 갈린다.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"말장난","entry_url":"cards/MEJE-KW-000275/index.html"},{"id":"MEJE-KW-000276","row_version":1,"title":"낯선 말투에 끌리는 관심","original":"Accent Interest","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 다른 사람의 독특한 억양이나 말투에 주의를 기울이고 그 소리에 호감이나 호기심을 느끼는 장면. 듣는 이의 반응이 두 사람의 관계를 시작하거나 변화시킨다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000276/index.html"},{"id":"MEJE-KW-000277","row_version":1,"title":"정체 공개 뒤 되돌아온 억양","original":"Accent Relapse","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"다른 출신이나 신분을 숨기던 인물이 정체가 드러난 직후, 이전에는 감추던 억양으로 갑자기 말하기 시작하는 전개. 말투의 변화로 비밀이 풀렸음을 관객에게 다시 확인시킨다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000277/index.html"},{"id":"MEJE-KW-000278","row_version":1,"title":"감정에 새어 나온 본래 억양","original":"Accent Slip-Up","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"다른 억양을 유지하던 인물이 놀라거나 흥분한 순간 평소 숨기던 말투를 잠깐 드러내는 장면. 한마디의 변화가 출신, 위장, 감정 상태를 암시한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000278/index.html"},{"id":"MEJE-KW-000279","row_version":1,"title":"한집 가족의 뜻밖의 억양 차이","original":"Accents Aren't Hereditary","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"같은 환경에서 자란 것으로 그려진 가족 인물들이 작품 안의 설명 없이 서로 크게 다른 억양을 쓰는 표현. 배경 설정과 들리는 말투 사이의 간격이 관객에게 드러난다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000279/index.html"},{"id":"MEJE-KW-000280","row_version":1,"title":"좋은 일은 빼고 불평만 말하기","original":"Accentuate the Negative","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 일상의 좋은 면은 당연하게 넘기고 불만스러운 일만 거듭 말하는 태도. 악의가 없어도 주변에는 냉소적인 사람으로 보이며 관계의 분위기를 바꾼다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-000280/index.html"},{"id":"MEJE-KW-000281","row_version":2,"title":"이야기를 위해 허용되는 비현실성","original":"Acceptable Breaks from Reality","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 속도와 이해를 위해 현실의 절차나 물리적 제약을 생략해도 관객이 자연스럽게 받아들이는 관습. 생략이 이야기의 흐름을 돕는 동안에는 문제로 부각되지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-000281/index.html"}]}.cards;